<script setup lang="ts">
import {localize} from './localization';

import {computed,ref,watch} from 'vue';
import {useSession} from './store';
import {useDraftHistory} from './modules/useDraftHistory';
const props=defineProps<{language:'zh'|'en'}>(),store=useSession(),zh=computed(()=>props.language==='zh'),snapshot=computed(()=>store.data.project?.surface?.customTemplate),targets=ref<Record<string,number>>({});
const panel=ref<HTMLElement>(),history=useDraftHistory(()=>targets.value,v=>{targets.value=v;},()=>!!panel.value?.getClientRects().length&&!!snapshot.value,()=>store.busy);
watch(()=>JSON.stringify([snapshot.value?.sourceHash,snapshot.value?.targets]),()=>{history.reset(()=>{const s=snapshot.value;targets.value=s?{...s.targets}:{};});},{immediate:true});
async function importFile(){const p=store.data.project;if(p)await store.run(()=>window.fpcad.importTemplate(p.id,p.revision));}
async function exportFile(){const p=store.data.project;if(p)await store.run(()=>window.fpcad.exportTemplate(p.id,p.revision));}
async function fit(){const p=store.data.project;if(p)await store.run(()=>window.fpcad.fitTemplate(p.id,p.revision,JSON.parse(JSON.stringify(targets.value))));}
</script>
<template><details ref="panel" class="custom-template-panel"><summary>{{zh?'自定义模板与 Morph 拟合':localize('Custom template and morph fit')}}</summary><p>{{zh?'仅导入本地 .fpctemplate / JSON 数据，含封闭网格、毫米 Morph 位移、权重范围、测量环、参数范围和许可备注。不会执行脚本或加载外链。拟合按文件定义的高度/网格边环测量，不是自动解剖定位或物理试穿；请确认模板来源和许可。':localize('Local .fpctemplate / JSON data only: closed mesh, morph deltas in mm, weight limits, measurement loops, target ranges and license. No scripts or external resources. Fits declared height/edge loops, not automatic anatomy detection or cloth simulation; verify source and license.')}}</p><button :disabled="store.busy" @click="importFile">{{zh?'导入自定义模板':localize('Import custom template')}}</button><template v-if="snapshot"><p>{{snapshot.definition.name}} · {{snapshot.definition.version}} · {{snapshot.definition.license}}<br>SHA256 {{snapshot.sourceHash}}</p><div class="custom-targets"><label v-for="m in snapshot.definition.measurements" :key="m.name">{{m.name}} mm ({{m.minMm}}–{{m.maxMm}})<input v-model.number="targets[m.name]" type="number" :min="m.minMm" :max="m.maxMm" step=".1"></label></div><button :disabled="store.busy" @click="fit">{{zh?'拟合测量并更新身体（可撤销）':localize('Fit measurements and update body (undoable)')}}</button><button :disabled="store.busy" @click="exportFile">{{zh?'导出原始模板定义':localize('Export original template definition')}}</button><p>{{zh?'实际测量 / 残差':localize('Actual measurements / residuals')}} · {{snapshot.solver.iterations}} iterations · E {{snapshot.solver.errorBefore.toExponential(3)}} → {{snapshot.solver.errorAfter.toExponential(3)}}</p><table><tbody><tr v-for="r in snapshot.measurements" :key="r.name"><td>{{r.name}}</td><td>{{r.targetMm.toFixed(2)}}</td><td>{{r.actualMm.toFixed(2)}}</td><td>{{r.residualMm.toFixed(3)}} mm</td></tr></tbody></table><p>{{zh?'无法在权重范围和公差内达到目标，或产生退化/翻转面时，更新会被拒绝。更新保留网格 ID，旧展开和花纹须重新计算；已接受纸样不自动覆盖。':localize('Unreachable targets or degenerate/inverted faces reject the update. Mesh IDs persist; recompute stale unwrap/markings. Accepted patterns are not overwritten.')}}</p></template></details></template>
<style scoped>details{margin:12px 0;border-top:1px solid var(--border);padding:10px 0}summary{cursor:pointer;font-weight:600}.custom-targets{display:flex;gap:12px;flex-wrap:wrap;margin:12px 0}.custom-targets label{width:160px}td{padding:3px 12px}p{overflow-wrap:anywhere;line-height:1.5}</style>
